import { createSlice } from '@reduxjs/toolkit';
import { increment } from '../counter/counterSlice';

const todosSlice = createSlice({
  name: 'todos',
  initialState: { items: [] },
  reducers: {
    addTodo: (state, action) => {
      state.items.push(action.payload);
    }
  },
  extraReducers: (builder) => {
    builder.addCase(increment, (state) => {
      // React to the counter incrementing
      state.lastIncrementedAt = Date.now();
    });
  }
});

import { createAsyncThunk, createSlice } from '@reduxjs/toolkit';

export const fetchUsers = createAsyncThunk(
  'users/fetchUsers',
  async () => {
    const response = await fetch('/api/users');
    return response.json();
  }
);

const notificationsSlice = createSlice({
  name: 'notifications',
  initialState: { message: null },
  reducers: {
    clearNotification: (state) => {
      state.message = null;
    }
  },
  extraReducers: (builder) => {
    builder
      .addCase(fetchUsers.pending, (state) => {
        state.message = 'Loading users...';
      })
      .addCase(fetchUsers.fulfilled, (state) => {
        state.message = 'Users loaded successfully!';
      })
      .addCase(fetchUsers.rejected, (state) => {
        state.message = 'Failed to load users.';
      });
  }
});

import { createSlice } from '@reduxjs/toolkit';

const logsSlice = createSlice({
  name: 'logs',
  initialState: [],
  reducers: {},
  extraReducers: (builder) => {
    builder
      .addMatcher(
        (action) => action.type.endsWith('/fulfilled'),
        (state, action) => {
          state.push({
            type: action.type,
            time: Date.now(),
            payload: action.payload
          });
        }
      );
  }
});

const logsSlice = createSlice({
  name: 'logs',
  initialState: [],
  reducers: {},
  extraReducers: (builder) => {
    builder.addDefaultCase((state, action) => {
      state.push({ action: action.type, time: Date.now() });
    });
  }
});

import { createAsyncThunk, createSlice } from '@reduxjs/toolkit';
import { fetchPosts } from '../posts/postsSlice';

export const fetchComments = createAsyncThunk(
  'comments/fetchComments',
  async (postId) => {
    const res = await fetch(`/api/posts/${postId}/comments`);
    return res.json();
  }
);

const commentsSlice = createSlice({
  name: 'comments',
  initialState: { items: [], postId: null, status: 'idle' },
  reducers: {
    setPostId: (state, action) => {
      state.postId = action.payload;
    }
  },
  extraReducers: (builder) => {
    builder
      .addCase(fetchComments.pending, (state) => {
        state.status = 'loading';
      })
      .addCase(fetchComments.fulfilled, (state, action) => {
        state.status = 'succeeded';
        state.items = action.payload;
      })
      .addCase(fetchComments.rejected, (state) => {
        state.status = 'failed';
      })
      .addCase(fetchPosts.fulfilled, (state, action) => {
        if (action.payload.length > 0) {
          state.postId = action.payload[0].id;
        }
      });
  }
});

